//! Actual, bounded development-only acceptance using private runtime connections.
//! No credentials enter the compiler role. Every negative DDL/GRANT rolls back.
use super::*;
use sqlx::{Connection, PgConnection, Row};
use std::{collections::BTreeSet, time::Duration};

pub async fn acceptance(expected: &str) -> Result<Value> {
    install::target(expected)?;
    execution::stage(
        "fresh.actual-acceptance",
        Duration::from_secs(120),
        inner(expected),
    )
    .await
}
async fn inner(expected: &str) -> Result<Value> {
    let before = verify(expected).await?;
    let business = super::business::actual().await?;
    let prefix = crate::credentials::role_prefix_from_env()?;
    let config = crate::credentials::connection_for_principal("migrator")?;
    if config.tls_key_identity.is_none() {
        return Err(refused(
            "actual acceptance requires the private mTLS migrator",
        ));
    }
    let mut conn = PgConnection::connect_with(&config.options)
        .await
        .map_err(|_| refused("actual acceptance connection failed"))?;
    install::login(&mut conn, &prefix, "migrator", true).await?;
    let outcome = exercise(&mut conn, &config.options, &prefix).await;
    execution::discard(conn).await;
    let mut evidence = outcome?;
    let after = verify(expected).await?;
    if before["fingerprints"] != after["fingerprints"] {
        return Err(refused("acceptance changed the final schema"));
    }
    evidence["final_verification"] = after;
    evidence["gateway_business_rollback"] = business;
    Ok(evidence)
}
async fn exercise(
    observer: &mut PgConnection,
    options: &sqlx::postgres::PgConnectOptions,
    prefix: &str,
) -> Result<Value> {
    let owner = format!("{prefix}owner");
    let mut negatives = 0;
    for ddl in [
        "ALTER TABLE gateway.gateway_a2a_tasks ADD COLUMN fresh_guard_probe text".to_owned(),
        "CREATE INDEX fresh_guard_probe_idx ON gateway.gateway_a2a_tasks(created_at)".to_owned(),
        "ALTER TABLE gateway.gateway_a2a_tasks ADD CONSTRAINT fresh_guard_probe_check CHECK(true)"
            .to_owned(),
        format!("GRANT UPDATE ON gateway.gateway_a2a_outbound_effects TO \"{prefix}gateway\""),
        "CREATE POLICY fresh_guard_probe_policy ON knowledge.pipeline_work USING(false)".to_owned(),
        "ALTER FUNCTION assistant.claim_runtime_thread_owner(uuid,uuid,text) SECURITY INVOKER"
            .to_owned(),
    ] {
        let mut tx = observer.begin().await?;
        crate::runner::set_role(&mut tx, &owner).await?;
        execution::execute(&mut tx, &ddl).await?;
        let snapshot: Value =
            sqlx::query_scalar("SELECT gateway.platform_fresh_schema_snapshot_v1()")
                .fetch_one(&mut *tx)
                .await?;
        if snapshot["catalog_matches"] != false || validate_snapshot(&snapshot).is_ok() {
            return Err(refused("actual structural/ACL/RLS drift was accepted"));
        }
        tx.rollback().await?;
        negatives += 1;
    }
    let definitions = source::compiled_definitions()?;
    let grants = crate::bootstrap::render_role_sql(&definitions.baseline_sql[2], prefix)?;
    let verify_sql = crate::bootstrap::render_role_sql(&definitions.verify_sql, prefix)?;
    let mut tx = observer.begin().await?;
    crate::runner::set_role(&mut tx, &owner).await?;
    execution::stage(
        "acceptance.complete-grant-stream",
        Duration::from_secs(60),
        execution::execute(&mut tx, &grants),
    )
    .await?;
    let rows = execution::stage(
        "acceptance.all-followup-checks",
        execution::SQL_LIMIT,
        async { Ok(sqlx::raw_sql(&verify_sql).fetch_all(&mut *tx).await?) },
    )
    .await?;
    let mut names = BTreeSet::new();
    for row in &rows {
        names.insert(row.try_get::<String, _>("check_name")?);
        row.try_get::<bool, _>("ok")?;
    }
    if rows.len() != 251 || names.len() != 251 || !names.contains("grant-matrix") {
        return Err(refused("incomplete actual baseline verification transport"));
    }
    tx.rollback().await?;
    // The historical baseline verdict is not modern schema acceptance. Restore
    // all grants before final current-source verification below.
    for active in [false, true] {
        let mut conn = PgConnection::connect_with(options)
            .await
            .map_err(|_| refused("cancellation regression connection failed"))?;
        install::login(&mut conn, prefix, "migrator", true).await?;
        let pid: i32 = sqlx::query_scalar("SELECT pg_backend_pid()")
            .fetch_one(&mut conn)
            .await?;
        let mut tx = conn.begin().await?;
        crate::runner::set_role(&mut tx, &owner).await?;
        execution::execute(&mut tx,"SET LOCAL statement_timeout='500ms';SET LOCAL idle_in_transaction_session_timeout='2s';SET LOCAL client_connection_check_interval='1s';CREATE TABLE public.fresh_cancel_owned_probe(id integer)").await?;
        let cancelled = if active {
            tokio::time::timeout(
                Duration::from_millis(20),
                sqlx::raw_sql("SELECT pg_sleep(30)").fetch_all(&mut *tx),
            )
            .await
            .is_err()
        } else {
            tokio::time::timeout(Duration::from_millis(20), std::future::pending::<()>())
                .await
                .is_err()
        };
        if !cancelled {
            return Err(refused("actual cancellation deadline did not fire"));
        }
        drop(tx);
        execution::discard(conn).await;
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let gone: bool = sqlx::query_scalar(
                    "SELECT NOT EXISTS(SELECT 1 FROM pg_catalog.pg_stat_activity WHERE pid=$1)",
                )
                .bind(pid)
                .fetch_one(&mut *observer)
                .await?;
                if gone {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(50)).await;
            }
            Ok::<(), sqlx::Error>(())
        })
        .await
        .map_err(|_| refused("cancelled owned backend remains present"))??;
        let absent: bool =
            sqlx::query_scalar("SELECT to_regclass('public.fresh_cancel_owned_probe') IS NULL")
                .fetch_one(&mut *observer)
                .await?;
        if !absent {
            return Err(refused("cancelled owned DDL did not roll back"));
        }
    }
    Ok(
        json!({"status":"passed_actual_fresh_schema_acceptance","database":DATABASE,
        "source_contract_sha256":source_sha256(),"catalog_drift_negatives":negatives,
        "complete_grant_statements":execution::statements(&grants)?.len(),"followup_checks":rows.len(),
        "actual_mtls":true,"idle_and_active_backend_cancellation":true,"cancelled_ddl_rolled_back":true,
        "historical_upgrade_acceptance":false,"all_probe_transactions_rolled_back":true}),
    )
}

use super::*;
use crate::application_guard::{self, ApplicationPrincipal};
use sqlx::PgConnection;
pub(super) async fn present(conn: &mut PgConnection) -> Result<bool> {
    Ok(sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname='platform_fresh_schema_state')").fetch_one(conn).await?)
}
/// The static contract contains no guessed catalog hash. Each real initializer
/// measures the final database; the reader checks its complete live catalog.
pub fn validate_snapshot(snapshot: &Value) -> Result<()> {
    let mut expected = admission_contract();
    let fingerprints = snapshot["fingerprints"]
        .as_object()
        .ok_or_else(|| refused("actual final fingerprint classes absent"))?;
    if fingerprints.len() != 4
        || ["structural", "acl", "extensions", "reference_data"]
            .iter()
            .any(|key| {
                fingerprints
                    .get(*key)
                    .and_then(Value::as_str)
                    .is_none_or(|h| {
                        h.len() != 64
                            || !h
                                .bytes()
                                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
                    })
            })
    {
        return Err(refused("actual final fingerprints malformed"));
    }
    expected["fingerprints"] = json!(fingerprints);
    if snapshot != &expected {
        return Err(refused(
            "fresh source, target, mode or real final catalog mismatch",
        ));
    }
    Ok(())
}
pub async fn admit_if_fresh(
    conn: &mut PgConnection,
    principal: ApplicationPrincipal,
) -> Result<bool> {
    if !present(conn).await? {
        return Ok(false);
    }
    let schema = if matches!(
        principal,
        ApplicationPrincipal::Runtime | ApplicationPrincipal::CapabilityWorker
    ) {
        "assistant"
    } else {
        "gateway"
    };
    let identity_sql = application_guard::PRINCIPAL_IDENTITY_SQL.replace(
        "platform_schema_admission_snapshot_v1",
        "platform_fresh_schema_snapshot_v1",
    );
    let identity: Value = sqlx::query_scalar(&identity_sql)
        .bind(schema)
        .fetch_one(&mut *conn)
        .await
        .map_err(|_| refused("fresh canonical reader identity unavailable"))?;
    application_guard::validate_principal_identity(&identity, principal)?;
    let snapshot: Value = sqlx::query_scalar(&format!(
        "SELECT {schema}.platform_fresh_schema_snapshot_v1()"
    ))
    .fetch_one(&mut *conn)
    .await
    .map_err(|_| refused("fresh reader denied or unavailable"))?;
    validate_snapshot(&snapshot)?;
    for query in crate::source_tools::service_successors::admission_checks(
        EPOCH,
        application_guard::principal_role_suffix(principal),
    )? {
        if !sqlx::query_scalar::<_, bool>(&query)
            .fetch_one(&mut *conn)
            .await
            .map_err(|_| refused("fresh exact service privilege probe unavailable"))?
        {
            return Err(refused("fresh exact service privilege contract refused"));
        }
    }
    Ok(true)
}

//! Real Gateway-role legacy import, hashes, idempotency and tenant negatives.
//! All fixture rows and writes are rolled back on the private runtime connection.
use super::*;
use sqlx::{Connection, PgConnection, Row};
use uuid::Uuid;
pub(super) async fn actual() -> Result<Value> {
    let prefix = crate::credentials::role_prefix_from_env()?;
    let c = crate::credentials::connection_for_principal("gateway")?;
    if c.tls_key_identity.is_none() {
        return Err(refused(
            "business acceptance requires actual Gateway file/mTLS",
        ));
    }
    let mut conn = PgConnection::connect_with(&c.options)
        .await
        .map_err(|_| refused("Gateway business connection unavailable"))?;
    install::login(&mut conn, &prefix, "gateway", true).await?;
    let mut outcome = exercise(&mut conn, &prefix, false).await;
    if let Ok(value) = &mut outcome {
        value["actual_gateway_file_mtls"] = json!(true);
    }
    execution::discard(conn).await;
    let value = outcome?;
    let op = operator::LocalOperator::from_env()?;
    let options = sqlx::postgres::PgConnectOptions::new()
        .host(
            op.socket_directory
                .to_str()
                .ok_or_else(|| refused("operator path encoding"))?,
        )
        .username(&op.username)
        .password("")
        .database(DATABASE)
        .ssl_mode(sqlx::postgres::PgSslMode::Disable)
        .application_name("fresh_business_rollback");
    let mut admin = PgConnection::connect_with(&options).await?;
    let safe:bool=sqlx::query_scalar("SELECT current_database()='gateway_dev_fresh' AND inet_client_addr() IS NULL AND current_user=session_user AND (SELECT rolsuper FROM pg_catalog.pg_roles WHERE rolname=current_user)").fetch_one(&mut admin).await?;
    if !safe {
        return Err(refused(
            "business operator is not independent local authority",
        ));
    }
    let mut tx = admin.begin().await?;
    role(&mut tx, &prefix, "gateway").await?;
    let seeded = exercise(&mut tx, &prefix, true).await?;
    tx.rollback().await?;
    execution::discard(admin).await;
    let mut denied_roles = Vec::new();
    for principal in [
        "migrator",
        "runtime",
        "capability_worker",
        "knowledge_api",
        "knowledge_worker",
    ] {
        let c = crate::credentials::connection_for_principal(principal)?;
        let mut conn = PgConnection::connect_with(&c.options).await?;
        install::login(&mut conn, &prefix, principal, true).await?;
        let allowed:bool=sqlx::query_scalar("SELECT NOT(count(*)=2 AND bool_and(NOT pg_catalog.has_function_privilege(current_user,p.oid,'EXECUTE'))) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='assistant' AND p.proname IN ('ensure_assistant_runtime_thread','import_assistant_legacy_session')").fetch_one(&mut conn).await?;
        if allowed {
            return Err(refused("unrelated principal has business entry EXECUTE"));
        }
        deny(
            &mut conn,
            false,
            Uuid::new_v4(),
            "x",
            "x",
            "x",
            "native",
            "42501",
        )
        .await?;
        deny(
            &mut conn,
            true,
            Uuid::new_v4(),
            "x",
            "x",
            "x",
            "native",
            "42501",
        )
        .await?;
        execution::discard(conn).await;
        denied_roles.push(principal);
    }
    Ok(
        json!({"gateway_file_mtls":value,"local_authority_seeded_gateway_role":seeded,"other_principals_actual_execute_denials":denied_roles}),
    )
}
