            new.replace(
                "pg_catalog.sha256(pg_catalog.convert_to(v_history::text, 'UTF8'))",
                PATTERNS[0].0
            )
            .replace(
                "pg_catalog.sha256(pg_catalog.convert_to(v_payload::text, 'UTF8'))",
                PATTERNS[1].0
            )
            .replace(PATTERNS[2].1, PATTERNS[2].0),
