/// Shared read-only admission contract; deployment preflight never invents app grants.
pub fn admission_checks(epoch: i32, principal: &str) -> Result<Vec<String>> {
    if epoch < 30 {
        return Ok(Vec::new());
    }
    let c = catalog()?;
    step(&c, epoch)?;
    let names: &[&str] = match principal {
        "gateway" => &[
            "gateway_sdk",
            "gateway_audit",
            "gateway_a2a",
            "local_node",
            "gateway_outbound",
            "partition_gateway",
        ],
        "runtime" => &["runtime", "partition_runtime"],
        "knowledge_worker" => &["knowledge_worker", "partition_knowledge_worker"],
        "knowledge_api" => &["knowledge_api", "partition_knowledge_api"],
        "capability_worker" => &["capability_worker", "partition_capability_worker"],
        _ => return Err(refused("unknown business principal")),
    };
    Ok(names
        .iter()
        .filter(|name| {
            c.admission_minimum_epochs
                .get(**name)
                .is_some_and(|minimum| *minimum <= epoch)
        })
        .map(|name| {
            c.admission_requirements
                .get(*name)
                .cloned()
                .ok_or_else(|| refused("admission requirement missing"))
        })
        .collect::<Result<Vec<_>>>()?)
}

//! Source035 supplements (never replaces) the frozen four-schema fingerprints.
//! partition_ops is outside that historical scope: its real catalog and minimal
//! ACL must be measured, source-bound, replay-checked and compared independently.
use super::*;
use crate::credentials;
use sqlx::{Connection, PgConnection};
const POLICY: &[u8] = include_bytes!(
    "../../../../../../../docs/design/proposals/service-successors/partition-authority-policy.json"
);
const POLICY_PATH: &str =
    "docs/design/proposals/service-successors/partition-authority-policy.json";
fn policy() -> Result<Value> {
    let c = catalog()?;
    if step(&c, 35)?.auxiliary_inputs_sha256.get(POLICY_PATH) != Some(&safe::sha256_bytes(POLICY)) {
        return Err(refused("compiled partition policy changed"));
    }
    serde_json::from_slice(POLICY).map_err(|_| refused("partition policy malformed"))
}
fn strings(v: &Value) -> Result<BTreeSet<String>> {
    v.as_array()
        .ok_or_else(|| refused("partition policy array missing"))?
        .iter()
        .map(|s| {
            s.as_str()
                .map(str::to_owned)
                .ok_or_else(|| refused("partition policy string missing"))
        })
        .collect()
}
fn list<'a>(v: &'a Value, key: &str) -> Result<&'a Vec<Value>> {
    v[key]
        .as_array()
        .ok_or_else(|| refused("partition catalog class missing"))
}
fn text<'a>(v: &'a Value, key: &str) -> Result<&'a str> {
